INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq1', 'q1', 'What is the time complexity of searching in a balanced BST?', CAST('["O(n)","O(log n)","O(n log n)","O(1)"]' AS jsonb), 1, 'In a balanced BST, each comparison eliminates half the remaining nodes.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq10', 'q4', 'At which OSI layer does TCP operate?', CAST('["Network","Transport","Session","Application"]' AS jsonb), 1, 'TCP operates at the Transport layer (Layer 4) of the OSI model.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq11', 'q4', 'What does DNS stand for?', CAST('["Dynamic Network Service","Domain Name System","Data Network Standard","Distributed Node Service"]' AS jsonb), 1, 'DNS (Domain Name System) translates human-readable domain names to IP addresses.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq12', 'q4', 'Which protocol is connectionless?', CAST('["TCP","HTTP","UDP","FTP"]' AS jsonb), 2, 'UDP (User Datagram Protocol) is connectionless — it sends packets without establishing a connection.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq2', 'q1', 'Which traversal visits nodes in ascending order for a BST?', CAST('["Pre-order","Post-order","In-order","Level-order"]' AS jsonb), 2, 'In-order traversal (left, root, right) visits BST nodes in sorted ascending order.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq3', 'q1', 'What is the maximum number of nodes in a binary tree of height h?', CAST('["2h","2h - 1","2^h - 1","2^(h+1) - 1"]' AS jsonb), 3, 'A complete binary tree of height h has at most 2^(h+1) - 1 nodes.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq4', 'q2', 'Which SQL clause is used to filter rows?', CAST('["ORDER BY","GROUP BY","WHERE","HAVING"]' AS jsonb), 2, 'WHERE filters individual rows before grouping.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq5', 'q2', 'What does INNER JOIN return?', CAST('["All rows from left table","All rows from right table","Matching rows from both tables","All rows from both tables"]' AS jsonb), 2, 'INNER JOIN returns only rows where the join condition is met in both tables.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq6', 'q2', 'Which normal form eliminates transitive dependencies?', CAST('["1NF","2NF","3NF","BCNF"]' AS jsonb), 2, '3NF removes transitive dependencies where non-key attributes depend on other non-key attributes.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq7', 'q3', 'Which scheduling algorithm can cause starvation?', CAST('["Round Robin","FCFS","Priority Scheduling","SJF"]' AS jsonb), 2, 'Priority Scheduling can starve low-priority processes if high-priority ones keep arriving.', 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq8', 'q3', 'What is the main advantage of Round Robin scheduling?', CAST('["Minimizes waiting time","Ensures fairness","Maximizes CPU utilization","Reduces context switches"]' AS jsonb), 1, 'Round Robin gives each process an equal time slice, ensuring fair CPU distribution.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, quiz_id, question, options, correct, explanation, order_idx) VALUES ('qq9', 'q3', 'In SJF scheduling, what information is required?', CAST('["Process priority","Burst time","Arrival time","Memory size"]' AS jsonb), 1, 'SJF (Shortest Job First) requires knowing the CPU burst time of each process.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f1', 'CS301', 'What is a Binary Search Tree?', 'A BST is a binary tree where each node''s left subtree contains only nodes with keys less than the node''s key, and the right subtree only nodes with greater keys.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f2', 'CS301', 'What is Big O notation?', 'Big O notation describes the upper bound of an algorithm''s time or space complexity, expressing how performance scales with input size.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f3', 'CS301', 'What is a Hash Table?', 'A data structure that maps keys to values using a hash function, providing O(1) average-case lookup, insertion, and deletion.', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f4', 'CS302', 'What is a Primary Key?', 'A primary key is a column (or set of columns) that uniquely identifies each row in a database table. It cannot be NULL.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f5', 'CS302', 'What is database normalization?', 'The process of organizing a database to reduce redundancy and improve data integrity by dividing large tables into smaller ones and defining relationships.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f6', 'CS303', 'What is a deadlock?', 'A deadlock occurs when two or more processes are blocked, each waiting for a resource held by another, creating a circular dependency.', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f7', 'CS303', 'What is virtual memory?', 'Virtual memory is a memory management technique that gives processes the illusion of a large, contiguous address space by using disk storage as an extension of RAM.', FALSE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, deck, front, back, ai_generated) VALUES ('f8', 'CS304', 'What is the difference between TCP and UDP?', 'TCP is connection-oriented, reliable, and ordered. UDP is connectionless, faster, but unreliable. TCP is used for web/email; UDP for streaming/gaming.', TRUE) ON CONFLICT (id) DO NOTHING;
