INSERT INTO public.forum_threads (id, title, course, author, author_role, views, tags, solved, last_activity, content, created_at) VALUES ('ft2', 'Difference between 2NF and 3NF?', 'CS302', 'Maria Garcia', 'student', 28, CAST('["normalization","2nf","3nf"]' AS jsonb), FALSE, '5 hours ago', 'Can someone explain the practical difference between 2NF and 3NF with an example?', '2026-09-13 17:10:49') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.forum_threads (id, title, course, author, author_role, views, tags, solved, last_activity, content, created_at) VALUES ('ft3', 'Why does Round Robin cause more context switches?', 'CS303', 'Alex Johnson', 'student', 19, CAST('["scheduling","round-robin"]' AS jsonb), FALSE, '1 day ago', 'I understand Round Robin is fair, but why does it cause more context switches than FCFS?', '2026-09-13 17:10:49') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.forum_replies (id, thread_id, author, author_role, content, timestamp) VALUES ('r1', 'ft1', 'Dr. Sarah Mitchell', 'lecturer', 'AVL rotations are triggered when the balance factor becomes +2 or -2.', '1 hour ago') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.forum_replies (id, thread_id, author, author_role, content, timestamp) VALUES ('r2', 'ft1', 'Maria Garcia', 'student', 'Great explanation! So a single rotation handles LL and RR cases?', '30 min ago') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.forum_replies (id, thread_id, author, author_role, content, timestamp) VALUES ('r3', 'ft2', 'Prof. James Carter', 'lecturer', '2NF removes partial dependencies; 3NF additionally removes transitive dependencies.', '4 hours ago') ON CONFLICT (id) DO NOTHING;
